attribute "tsugumi";
namespace exo;
table LightCurveFiles { value:string; }
table Outputs { data:LightCurveFiles (required, tsugumi: "directory"); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [ ps.certifi ];
  };
}

